	// Interfaces §5) — persisted verbatim, no parsing here.
	cmd := exec.CommandContext(pctx, ffprobeBin,
		"-v", "quiet",
		"-print_format", "json",
		"-show_format",
		"-show_streams",
		"-show_chapters",
		absPath,
	)
